1	/**
2	 * Per-org feature flag overrides.
3	 *
4	 * Owner D. Each row shows three separate facts that are easy to conflate: what
5	 * the definition's rollout strategy says, whether the org has an override, and
6	 * what `isEnabled()` actually returns right now. Only `overridable` flags can be
7	 * changed here.
8	 *
9	 * Must call (do not reimplement): can, isEnabled
10	 */
11	
12	import { notFound } from "next/navigation";
13	import type { Metadata } from "next";
14	import { toggleFeatureFlagAction } from "@/actions/flags/toggle-flag";
15	import { FEATURE_FLAG_DEFINITIONS } from "@/config/feature-flags";
16	import { isEnabled } from "@/lib/feature-flags";
17	import { can } from "@/lib/permissions";
18	import { buildFlagContext } from "@/server/services/feature-flag-service";
19	import type { FeatureFlagKey } from "@/types/feature-flag";
20	import { loadTenantContext } from "../../_lib/tenant-context";
21	import { FlagToggleList, type FlagRow } from "./flag-toggle-list";
22	
23	type PageParams = { orgSlug: string };
24	
25	export const dynamic = "force-dynamic";
26	
27	export const metadata: Metadata = {
28	  title: "Feature flags",
29	};
30	
31	export default async function Page(props: {
32	  params: Promise<PageParams>;
33	  searchParams: Promise<Record<string, string | string[] | undefined>>;
34	}) {
35	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
36	  const { orgSlug } = await props.params;
37	  await props.searchParams;
38	
39	  const { org, actor } = await loadTenantContext(orgSlug);
40	
41	  const allowed = can(actor, "org:manage_flags", {
42	    kind: "organization",
43	    orgId: org.id,
44	  });
45	  if (!allowed) {
46	    notFound();
47	  }
48	
49	  const context = buildFlagContext(actor, org);
50	  const overrides = new Set(org.settings.enabledFlagOverrides);
51	
52	  const rows: readonly FlagRow[] = Object.values(FEATURE_FLAG_DEFINITIONS).map(
53	    (definition) => ({
54	      key: definition.key,
55	      label: definition.label,
56	      description: definition.description,
57	      strategy: describeStrategy(definition.strategy.kind),
58	      overridable: definition.overridable,
59	      overridden: overrides.has(definition.key),
60	      enabled: isEnabled(definition.key, context),
61	    }),
62	  );
63	
64	  async function toggle(flag: FeatureFlagKey, enabled: boolean): Promise<void> {
65	    "use server";
66	    await toggleFeatureFlagAction({ orgId: org.id, flag, enabled });
67	  }
68	
69	  return (
70	    <div className="space-y-8">
71	      <header>
72	        <h1 className="text-xl font-semibold tracking-tight">Feature flags</h1>
73	        <p className="mt-1 text-sm text-slate-600">
74	          Flags gated on your plan turn on automatically. Overridable ones can be
75	          switched here for {org.name} only.
76	        </p>
77	      </header>
78	
79	      <FlagToggleList rows={rows} onToggle={toggle} />
80	    </div>
81	  );
82	}
83	
84	function describeStrategy(kind: string): string {
85	  switch (kind) {
86	    case "on":
87	      return "Always on";
88	    case "off":
89	      return "Off by default";
90	    case "plan":
91	      return "Included from a certain plan";
92	    case "role":
93	      return "Limited by role";
94	    case "percentage":
95	      return "Percentage rollout";
96	    default:
97	      return kind;
98	  }
99	}
